200	    @Override
201	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner != null) {
204	            Pet pet = owner.getPet(petId);
205	            if (pet != null) {
206	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
207	            }
208	        }
209	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	    }
211	
212	    /**
213	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
214	     * offending field is collected so the caller learns exactly which values must be supplied.
215	     *
216	     * @param ownerFieldsDto the submitted owner payload
217	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
218	     *         telephone is missing or blank
219	     */
220	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
221	        List<String> missingFields = new ArrayList<>();
222	        if (isBlank(ownerFieldsDto.getFirstName())) {
223	            missingFields.add("firstName");
224	        }
225	        if (isBlank(ownerFieldsDto.getLastName())) {
226	            missingFields.add("lastName");
227	        }
228	        if (isBlank(ownerFieldsDto.getAddress())) {
229	            missingFields.add("address");
230	        }
231	        if (isBlank(ownerFieldsDto.getCity())) {
232	            missingFields.add("city");
233	        }
234	        if (isBlank(ownerFieldsDto.getTelephone())) {
235	            missingFields.add("telephone");
236	        }
237	        if (!missingFields.isEmpty()) {
238	            throw new MissingOwnerFieldsException(missingFields);
239	        }
240	    }
241	
242	    private boolean isBlank(String value) {
243	        return value == null || value.isBlank();
244	    }
245	
246	    /**
247	     * Normalizes a telephone number supplied on create by removing every non-digit character and
248	     * requiring the result to be exactly ten digits. The normalized ten-digit value is what gets
249	     * stored and returned.
250	     *
251	     * @param telephone the raw telephone value from the request
252	     * @return the normalized ten-digit telephone
253	     * @throws InvalidOwnerFieldsException if the value is not exactly ten digits after stripping
254	     */
255	    private String normalizeTelephone(String telephone) {
256	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
257	        if (digits.length() != 10) {
258	            throw new InvalidOwnerFieldsException(List.of("telephone"));
259	        }
260	        return digits;
261	    }
262	
263	    /**
264	     * Rejects an owner create whose normalized telephone is already used by any other owner. Every
265	     * existing owner's stored telephone is normalized the same way (non-digits stripped) before
266	     * comparison so the uniqueness check is independent of the punctuation a caller supplied.
267	     *
268	     * @param normalizedTelephone the normalized ten-digit telephone of the owner being created
269	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
270	     */
271	    private void rejectDuplicateTelephone(String normalizedTelephone) {
272	        boolean inUse = this.clinicService.findAllOwners().stream()
273	            .map(Owner::getTelephone)
274	            .filter(existing -> existing != null)
275	            .map(existing -> existing.replaceAll("\\D", ""))
276	            .anyMatch(normalizedTelephone::equals);
277	        if (inUse) {
278	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
279	        }
280	    }
281	}
